"""Topic path subscription matcher."""
import re


def is_topic_subscribed(subscribed_pattern: str, event_topic: str) -> bool:
    """Check if event_topic matches the subscribed_pattern respecting hierarchical boundaries."""
    # Exact match
    if subscribed_pattern == event_topic:
        return True

    # Handle wildcards per H06
    if "*" in subscribed_pattern:
        # Escape all regex special characters except our wildcards
        regex_str = re.escape(subscribed_pattern)
        # Replace escaped wildcards with regex equivalents
        # ** matches any number of segments (including zero additional segments if at end, but usually implies children)
        # * matches exactly one segment
        # Since separator is ::, a segment contains no ::. We assume segments don't contain ':' for simplicity
        # as per standard path conventions unless specified otherwise.
        regex_str = regex_str.replace(r"\*\*", ".*")
        regex_str = regex_str.replace(r"\*", "[^:]+")

        full_regex = "^" + regex_str + "$"
        try:
            return bool(re.match(full_regex, event_topic))
        except re.error:
            return False

    # No wildcards: ensure boundary check to prevent prefix leaks (e.g., "orders" vs "orders_admin")
    if event_topic.startswith(subscribed_pattern + "::"):
        return True

    return False


def clean_topic_segment(topic: str) -> str:
    return topic.strip().lower()


def is_wildcard_subscription(pattern: str) -> bool:
    return pattern.strip() in ("*", "**")
